steps.unassigned_by_reason:
var rows = JSON.parse(value), by = {}, keys = [], out = [];
for (var i = 0; i < rows.length; i++) { if (rows[i].state !== 'UNASSIGNED') continue; var r = rows[i]['unassigned.reason'] || 'unknown'; if (!by[r]) { by[r] = 0; keys.push(r); } by[r]++; }
keys.sort(function (a, b) { return by[b] - by[a]; });
for (var j = 0; j < keys.length; j++) out.push(keys[j] + ': ' + by[keys[j]]);
return out.length ? out.join(', ') : 'none';

steps.indices_red:
var rows = JSON.parse(value), n = 0;
for (var i = 0; i < rows.length; i++) if (rows[i].health === 'red') n++;
return n;

steps.indices_yellow:
var rows = JSON.parse(value), n = 0;
for (var i = 0; i < rows.length; i++) if (rows[i].health === 'yellow') n++;
return n;

steps.slm_policies:
var p = JSON.parse(value), n = 0;
for (var k in p) if (p.hasOwnProperty(k)) n++;
return n;

steps.slm_last_success_age:
var p = JSON.parse(value), newest = 0;
for (var k in p) { if (!p.hasOwnProperty(k)) continue; var s = p[k].last_success; if (s && s.time > newest) newest = s.time; }
if (!newest) throw 'no SLM policy has a successful snapshot';
return Math.round((Date.now() - newest) / 1000);

steps.tp_get_queue:
var rows = JSON.parse(value), n = 0;
for (var i = 0; i < rows.length; i++) if (rows[i].name === 'get') n += Number(rows[i].queue) || 0;
return n;

steps.tp_get_rejected:
var rows = JSON.parse(value), n = 0;
for (var i = 0; i < rows.length; i++) if (rows[i].name === 'get') n += Number(rows[i].rejected) || 0;
return n;

steps.cpu_max:
var nodes = JSON.parse(value).nodes || {}, max = -1;
for (var k in nodes) { if (!nodes.hasOwnProperty(k)) continue; var c = ((nodes[k].os || {}).cpu || {}).percent; if (typeof c === 'number' && c > max) max = c; }
if (max < 0) throw 'no node reported its CPU';
return max;

steps.cpu_avg:
var nodes = JSON.parse(value).nodes || {}, sum = 0, n = 0;
for (var k in nodes) { if (!nodes.hasOwnProperty(k)) continue; var c = ((nodes[k].os || {}).cpu || {}).percent; if (typeof c === 'number') { sum += c; n++; } }
if (!n) throw 'no node reported its CPU';
return Math.round(sum / n * 10) / 10;

steps.tasks_long:
var rows = JSON.parse(value), limit = Number('{$EP.TASK.LONG}') || 300, n = 0;
for (var i = 0; i < rows.length; i++) if (Number(rows[i].running_time_ns) / 1e9 > limit) n++;
return n;

steps.aliases_no_write:
var rows = JSON.parse(value), by = {}, keys = [], n = 0;
for (var i = 0; i < rows.length; i++) { var a = rows[i].alias; if (!by[a]) { by[a] = { count: 0, write: false }; keys.push(a); } by[a].count++; if (rows[i].is_write_index === 'true') by[a].write = true; }
for (var j = 0; j < keys.length; j++) if (by[keys[j]].count > 1 && !by[keys[j]].write) n++;
return n;

steps.jump_part:
var n = __N__, paths = __PATHS__, parts = [], re = /\r?\n?@@HTTP (\d{3})@@\r?\n?/g, last = 0, m;
while ((m = re.exec(value)) !== null) { parts.push({ body: value.slice(last, m.index), code: m[1] }); last = re.lastIndex; }
if (!parts.length) throw 'curl.exe did not run on the jump host: ' + value.replace(/\s+/g, ' ').slice(0, 200);
var p = parts[n];
if (!p) throw 'no answer for ' + paths[n];
if (p.code === '000') throw 'Elasticsearch did not answer ' + paths[n] + ' through the jump host';
if (p.code !== '200') { var why = ''; try { var e = JSON.parse(p.body).error; why = e && (e.reason || e.type) ? ': ' + (e.reason || e.type) : ''; } catch (x) {}
  throw 'Elasticsearch answered ' + p.code + ' for ' + paths[n] + why; }
return p.body;

steps.jump_problem:
var paths = __PATHS__, re = /@@HTTP (\d{3})@@/g, m, i = 0, out = [];
if (value.indexOf('@@HTTP') < 0) return 'curl.exe did not run on the jump host: ' + value.replace(/\s+/g, ' ').slice(0, 200);
while ((m = re.exec(value)) !== null) { if (m[1] !== '200') out.push((m[1] === '000' ? 'no answer' : 'HTTP ' + m[1]) + ' for ' + paths[i]); i++; }
return out.join('; ');
